import functools
import time

def ttl_cache(maxsize=128, ttl=600, timer=time.monotonic, typed=False):
    """Decorator to wrap a function with a memoizing callable that saves
    up to `maxsize` results based on a Least Recently Used (LRU)
    algorithm with a per-item time-to-live (TTL) value.
    """
    def decorator(func):
        cache = functools.lru_cache(maxsize=maxsize, typed=typed)
        cache_with_timestamp = {}

        @functools.wraps(func)
        def wrapper(*args, **kwargs):
            key = cache._make_key(args, kwargs, typed)
            if key in cache_with_timestamp:
                timestamp, value = cache_with_timestamp[key]
                if timer() - timestamp < ttl:
                    return value
                else:
                    cache_with_timestamp.pop(key)
                    cache.cache_clear()

            result = func(*args, **kwargs)
            cache_with_timestamp[key] = (timer(), result)
            return result

        return wrapper

    return decorator

