def absorb(self, args):
    """
    Given an `args` sequence of expressions, return a new list of expression
    applying absorption and negative absorption.

    See https://en.wikipedia.org/wiki/Absorption_law

    Absorption::

        A & (A | B) = A, A | (A & B) = A

    Negative absorption::

        A & (~A | B) = A & B, A | (~A & B) = A | B
    """
    from itertools import combinations

    def apply_absorption(expr1, expr2):
        if isinstance(expr1, tuple) and isinstance(expr2, tuple):
            op1, a1, b1 = expr1
            op2, a2, b2 = expr2
            if op1 == '&' and op2 == '|':
                if a1 == a2:
                    return a1
                if a1 == (~a2):
                    return (op1, a1, b2)
            if op1 == '|' and op2 == '&':
                if a1 == a2:
                    return a1
                if a1 == (~a2):
                    return (op1, a1, b2)
        return None

    result = list(args)
    for expr1, expr2 in combinations(args, 2):
        absorbed_expr = apply_absorption(expr1, expr2)
        if absorbed_expr:
            result.append(absorbed_expr)
            result.remove(expr1)
            result.remove(expr2)
            return self.absorb(result)  # Recursively apply absorption

    return result

