        if not os.path.exists(inventory_path):
            raise FileNotFoundError(f"Inventory file not found for version: {version_dir}")

        version_inventory = self.load_inventory(inventory_path)

        for item, details in version_inventory.items():
            content_path = os.path.join(version_dir, item)
            if not os.path.exists(content_path):
                raise FileNotFoundError(f"Content file not found: {content_path}")

            current_digest = self.calculate_digest(content_path)
            if item in root_inventory:
                if current_digest != root_inventory[item]['digest']:
                    raise ValueError(f"Digest mismatch for {item} in version {version_dir}")
            else:
                if item not in content_digests:
                    content_digests[item] = current_digest
                elif content_digests[item] != current_digest:
                    raise ValueError(f"Inconsistent digest for {item} across versions")

    for item, digest in content_digests.items():
        if item not in root_inventory or root_inventory[item]['digest'] != digest:
            raise ValueError(f"Digest mismatch for {item} in root inventory")

def load_inventory(self, inventory_path):
    import json
    with open(inventory_path, 'r') as f:
        return json.load(f)

def calculate_digest(self, file_path):
    hasher = hashlib.sha256()
    with open(file_path, 'rb') as f:
        for chunk in iter(lambda: f.read(4096), b""):
            hasher.update(chunk)
    return hasher.hexdigest()

