from inspect import signature

def _verify(iface, candidate, tentative=False, vtype=None):
    errors = []

    if not tentative and not iface.providedBy(candidate):
        errors.append(f"Candidate does not claim to provide the interface {iface.__name__}.")

    required_attributes = set(getattr(iface, '__attrs__', []))
    required_methods = set(getattr(iface, '__methods__', []))

    candidate_attributes = set(vars(candidate))
    candidate_methods = {name for name, value in vars(candidate).items() if callable(value)}

    missing_attributes = required_attributes - candidate_attributes
    if missing_attributes:
        for attr in missing_attributes:
            errors.append(f"Interface {iface.__name__} requires attribute '{attr}' which is not defined on candidate.")

    missing_methods = required_methods - candidate_methods
    if missing_methods:
        for method in missing_methods:
            errors.append(f"Interface {iface.__name__} requires method '{method}' which is not defined on candidate.")

    for method in required_methods.intersection(candidate_methods):
        expected_sig = signature(getattr(iface, method))
        candidate_sig = signature(getattr(candidate, method))
        if expected_sig != candidate_sig:
            errors.append(f"Method '{method}' on candidate has signature {candidate_sig}, but expected signature is {expected_sig}.")

    if errors:
        if len(errors) == 1:
            raise Invalid(errors[0])
        else:
            raise Invalid("\n".join(errors))

    return True

